# frozen_string_literal: true

module MEPStudio
  # Builds linear MEP runs (rectangular / round duct, pipe, cable tray, conduit)
  # along a polyline using Face#followme. Elbows are generated by filleting the
  # path corners, so the result is one clean solid per run.
  module RunBuilder
    module_function

    # pts  : Array of [x,y,z] (inches) in the coordinates of +entities+
    # opts : 'kind' (duct|pipe|tray), 'shape' (rect|round), 'system',
    #        'width','height','diameter' (mm), 'dn', 'insulation' (mm),
    #        'elbow_radius' (factor of size), 'show_insulation'
    def build(entities, pts, opts)
      kind = opts['kind']
      shape = kind == 'pipe' ? 'round' : (kind == 'tray' ? 'tray' : opts['shape'])
      w, h = size_inch(opts, shape)
      raw = Geo.clean_path(pts)
      raise 'Path needs at least 2 different points' if raw.size < 2

      bend_base = shape == 'rect' || shape == 'tray' ? w : w
      radius = opts['elbow_radius'].to_f * bend_base
      radius = [radius, bend_base * 0.55].max if radius > 0 && shape != 'round'
      path = radius > 0 ? Geo.fillet_path(raw, radius, shape == 'round' ? 6 : 4) : raw

      group = entities.add_group
      sweep(group.entities, path, shape, w, h)
      Util.soften(group.entities)
      sys = opts['system']
      group.material = Util.material(sys)
      group.layer = Util.system_tag(sys)

      ins = opts['insulation'].to_f
      if ins > 0 && Util.yes?(opts['show_insulation']) && shape != 'tray'
        ig = group.entities.add_group
        sweep(ig.entities, path, shape, w + 2 * Util.mm(ins), h + 2 * Util.mm(ins))
        Util.soften(ig.entities)
        ig.material = Util.plain_material('MEP_Insulation', [235, 235, 210], 0.35)
        ig.name = 'Insulation'
      end

      write_attrs(group, kind, shape, raw, path, opts)
      group
    end

    def size_inch(opts, shape)
      case shape
      when 'round'
        d = if opts['kind'] == 'pipe'
              Catalog::PIPE_OD[opts['dn'].to_i] || opts['diameter'].to_f
            else
              opts['diameter'].to_f
            end
        [Util.mm(d), Util.mm(d)]
      else
        [Util.mm(opts['width']), Util.mm(opts['height'])]
      end
    end

    def sweep(ents, path, shape, w, h)
      p0 = path[0]
      d0 = Geo.norm(Geo.sub(path[1], p0))
      wa, ha = Geo.section_axes(d0)
      edges = ents.add_edges(path.map { |p| Util.a_pt(p) })
      face = case shape
             when 'round'
               circ = ents.add_circle(Util.a_pt(p0), Util.a_vec(d0), w / 2.0, w > Util.mm(150) ? 24 : 16)
               ents.add_face(circ)
             when 'tray'
               t = Util.mm(2.0)
               prof = [[-w / 2, h / 2], [-w / 2, -h / 2], [w / 2, -h / 2], [w / 2, h / 2],
                       [w / 2 - t, h / 2], [w / 2 - t, -h / 2 + t], [-w / 2 + t, -h / 2 + t], [-w / 2 + t, h / 2]]
               ents.add_face(prof.map { |a, b| Util.a_pt(Geo.add(p0, Geo.add(Geo.mul(wa, a), Geo.mul(ha, b)))) })
             else
               prof = [[-1, -1], [1, -1], [1, 1], [-1, 1]]
               ents.add_face(prof.map { |a, b| Util.a_pt(Geo.add(p0, Geo.add(Geo.mul(wa, a * w / 2), Geo.mul(ha, b * h / 2)))) })
             end
      raise 'Could not create section profile' unless face
      ok = face.followme(edges)
      raise 'Follow Me failed for this path (try a larger segment length or smaller elbow radius)' unless ok
      leftovers = edges.select { |e| e.valid? && e.faces.empty? }
      ents.erase_entities(leftovers) unless leftovers.empty?
    end

    def write_attrs(group, kind, shape, raw, path, opts)
      len_mm = Util.to_mm(Geo.path_length(path))
      size = size_label(kind, shape, opts)
      group.name = "#{kind.capitalize} #{opts['system']} #{size}"
      Util.set_attrs(group,
                     'type' => kind,
                     'system' => opts['system'],
                     'shape' => shape,
                     'width' => opts['width'].to_f,
                     'height' => opts['height'].to_f,
                     'diameter' => shape == 'round' ? Util.to_mm(size_inch(opts, 'round')[0]) : 0.0,
                     'dn' => opts['dn'].to_i,
                     'insulation' => opts['insulation'].to_f,
                     'elbow_radius' => opts['elbow_radius'].to_f,
                     'show_insulation' => Util.yes?(opts['show_insulation']),
                     'size' => size,
                     'length_mm' => len_mm.round(1),
                     'path' => raw.flatten,
                     'centerline' => path.flatten)
    end

    def size_label(kind, shape, opts)
      if kind == 'pipe'
        dn = opts['dn'].to_i
        "DN#{dn} (#{Catalog::DN_INCH[dn]})"
      elsif shape == 'round'
        "Ø#{opts['diameter'].to_i}"
      else
        "#{opts['width'].to_i}x#{opts['height'].to_i}"
      end
    end

    # Opts hash stored in an existing run (used by edit / resize).
    def opts_from(group)
      a = Util.attrs(group)
      {
        'kind' => a['type'], 'shape' => a['shape'] == 'tray' ? 'rect' : a['shape'],
        'system' => a['system'], 'width' => a['width'], 'height' => a['height'],
        'diameter' => a['diameter'], 'dn' => a['dn'], 'insulation' => a['insulation'],
        'elbow_radius' => a['elbow_radius'], 'show_insulation' => a['show_insulation']
      }
    end

    def path_from(group, key = 'path')
      flat = group.get_attribute(DICT, key) || []
      flat.each_slice(3).map { |s| s.map(&:to_f) }
    end

    # Rebuild run with new options, preserving its position.
    def rebuild(group, new_opts)
      parent_ents = group.parent.entities
      tr = group.transformation
      pts = path_from(group).map { |p| Util.pt_a(Util.a_pt(p).transform(tr)) }
      opts = opts_from(group).merge(new_opts)
      layer = group.layer
      g = build(parent_ents, pts, opts)
      g.layer = layer if opts['system'] == Util.attrs(group)['system']
      group.erase!
      g
    end
  end
end
